    "type": "trigger",
    "name": "file_authority_gc_execution_guard",
    "tableName": "file_location_gc_ledger",
    "sql": "CREATE TRIGGER file_authority_gc_execution_guard BEFORE UPDATE ON file_location_gc_ledger\nWHEN NEW.state='deleting' AND (SELECT mode FROM file_authority_control WHERE singleton=1)='active' BEGIN\n SELECT RAISE(ABORT,'File execution is paused on this installation')\n WHERE NOT EXISTS(SELECT 1 FROM file_authority_runtime_guard WHERE singleton=1 AND enabled=1);\nEND"
