    "name": "file_shadow_attempts_candidate_insert_guard",
    "tableName": "file_shadow_attempts",
    "sql": "CREATE TRIGGER file_shadow_attempts_candidate_insert_guard BEFORE INSERT ON file_shadow_attempts BEGIN SELECT RAISE(ABORT,'Shadow attempt candidate contract mismatch') WHERE NOT(NEW.candidate_file_id IS NULL OR EXISTS(SELECT 1 FROM file_shadow_operations o JOIN files f ON f.id=NEW.candidate_file_id JOIN file_locations l ON l.id=NEW.candidate_location_id AND l.file_id=f.id WHERE o.id=NEW.operation_id AND f.purpose IS o.purpose AND f.access_scope IS o.access_scope AND f.expected_byte_size IS NEW.verified_byte_size AND f.expected_sha256 IS NEW.verified_sha256 AND NEW.verified_byte_size IS o.source_expected_byte_size AND NEW.verified_sha256 IS o.source_expected_sha256 AND l.storage_profile_id IS o.destination_profile_id AND l.object_key IS NEW.candidate_object_key AND NOT(l.storage_profile_id IS o.source_profile_id AND l.object_key IS o.source_object_key) AND (NEW.state IN('verified','published') OR NOT EXISTS(SELECT 1 FROM file_publications p WHERE p.file_id=f.id)) AND NOT EXISTS(SELECT 1 FROM file_location_gc_ledger g WHERE g.location_id=l.id AND g.state IN('deleting','deleted')))); END"
