    "name": "file_shadow_decisions_derivation_guard",
    "tableName": "file_shadow_decisions",
    "sql": "CREATE TRIGGER file_shadow_decisions_derivation_guard BEFORE INSERT ON file_shadow_decisions BEGIN SELECT RAISE(ABORT,'Shadow preview binding requires its exact verified derivation') WHERE NEW.decision='resolved' AND EXISTS(SELECT 1 FROM file_shadow_occurrences o JOIN file_usable_publications f ON f.file_id=NEW.file_id WHERE o.id=NEW.occurrence_id AND f.purpose='derived_preview' AND NOT EXISTS(\n SELECT 1 FROM file_derivations d JOIN file_usable_publications source ON source.file_id=d.source_file_id WHERE d.derived_file_id=NEW.file_id AND d.trust_state='verified' AND (\n (o.consumer_kind='attachment_derivative' AND d.generator=json_extract(o.source_json,'$.derivative_kind') AND d.generator_version=json_extract(o.source_json,'$.generator_version') AND d.source_verified_sha256=json_extract(o.source_json,'$.source_sha256') AND source.verified_byte_size=json_extract(o.source_json,'$.source_byte_size'))\n OR (o.consumer_kind='event' AND o.file_slot='thumbnail' AND EXISTS(SELECT 1 FROM file_shadow_heads h JOIN file_shadow_decisions sd ON sd.occurrence_id=h.occurrence_id WHERE h.consumer_kind='event' AND h.consumer_id=o.consumer_id AND h.consumer_sub_id='' AND h.file_slot='primary' AND h.present=1 AND sd.file_id=d.source_file_id))\n OR (o.consumer_kind='comment_submission_item' AND EXISTS(SELECT 1 FROM file_shadow_heads h JOIN file_shadow_decisions sd ON sd.occurrence_id=h.occurrence_id WHERE h.consumer_kind='comment_submission_item' AND h.consumer_id=json_extract(o.source_json,'$.related_item_id') AND h.consumer_sub_id='' AND h.file_slot='primary' AND h.present=1 AND sd.file_id=d.source_file_id))))); END"
