    "tableName": "file_shadow_decisions",
    "sql": "CREATE TRIGGER file_shadow_decisions_purpose_guard BEFORE INSERT ON file_shadow_decisions BEGIN SELECT RAISE(ABORT,'Shadow decision purpose does not match its typed business slot') WHERE NEW.decision='resolved' AND NOT EXISTS(SELECT 1 FROM file_shadow_occurrences o JOIN file_usable_publications f ON f.file_id=NEW.file_id WHERE o.id=NEW.occurrence_id AND f.purpose= CASE WHEN o.consumer_kind IN('state_representation_asset','run_step_asset','run_step_comment','state_verification') OR(o.consumer_kind='event' AND o.file_slot='primary') THEN 'embedded_content' WHEN o.consumer_kind IN('metrology_template_reference','project_content_attachment') THEN 'research_source' WHEN o.consumer_kind IN('import','template_version') THEN 'provenance' WHEN o.consumer_kind='attachment_derivative' OR(o.consumer_kind='event' AND o.file_slot='thumbnail') THEN 'derived_preview' WHEN o.consumer_kind='comment_submission_item' THEN o.expected_purpose END ); END"
