    "name": "project_attachment_occurrence_mime_insert_guard",
    "tableName": "project_content_attachments",
    "sql": "CREATE TRIGGER project_attachment_occurrence_mime_insert_guard\nBEFORE INSERT ON project_content_attachments\nBEGIN\n  SELECT RAISE(ABORT, 'project attachment MIME type is invalid')\n  WHERE NEW.mime_type IS NULL\n    OR length(NEW.mime_type) NOT BETWEEN 3 AND 200\n    OR trim(NEW.mime_type) <> NEW.mime_type\n    OR instr(NEW.mime_type, char(0)) > 0\n    OR NEW.mime_type GLOB '*[^ -~]*'\n    OR instr(\n      trim( CASE\n        WHEN instr(NEW.mime_type, ';') > 0\n          THEN substr(NEW.mime_type, 1, instr(NEW.mime_type, ';') - 1)\n        ELSE NEW.mime_type\n      END ),\n      '/'\n    ) <= 1\n    OR instr(\n      trim( CASE\n        WHEN instr(NEW.mime_type, ';') > 0\n          THEN substr(NEW.mime_type, 1, instr(NEW.mime_type, ';') - 1)\n        ELSE NEW.mime_type\n      END ),\n      '/'\n    ) >= length(trim( CASE\n      WHEN instr(NEW.mime_type, ';') > 0\n        THEN substr(NEW.mime_type, 1, instr(NEW.mime_type, ';') - 1)\n      ELSE NEW.mime_type\n    END ))\n    OR instr(\n      substr(\n        trim( CASE\n          WHEN instr(NEW.mime_type, ';') > 0\n            THEN substr(NEW.mime_type, 1, instr(NEW.mime_type, ';') - 1)\n          ELSE NEW.mime_type\n        END ),\n        instr(trim( CASE\n          WHEN instr(NEW.mime_type, ';') > 0\n            THEN substr(NEW.mime_type, 1, instr(NEW.mime_type, ';') - 1)\n          ELSE NEW.mime_type\n        END ), '/') + 1\n      ),\n      '/'\n    ) > 0\n    OR trim( CASE\n      WHEN instr(NEW.mime_type, ';') > 0\n        THEN substr(NEW.mime_type, 1, instr(NEW.mime_type, ';') - 1)\n      ELSE NEW.mime_type\n    END ) GLOB '*[^A-Za-z0-9!#$%&''*+.^_`|~/-]*';\nEND"
