    "tableName": "run_step_comments",
    "sql": "CREATE TRIGGER run_step_comments_active_file_required_update BEFORE UPDATE ON run_step_comments\nWHEN (SELECT mode FROM file_authority_control WHERE singleton=1)='active' AND (NEW.asset_id IS NOT NULL AND NEW.file_id IS NULL)\nBEGIN SELECT RAISE(ABORT,'Active consumer requires a typed File binding'); END"
