    "name": "template_versions_active_file_required_insert",
    "tableName": "template_versions",
    "sql": "CREATE TRIGGER template_versions_active_file_required_insert BEFORE INSERT ON template_versions\nWHEN (SELECT mode FROM file_authority_control WHERE singleton=1)='active' AND (NULLIF(trim(NEW.source_asset_key),'') IS NOT NULL AND NEW.source_file_id IS NULL AND NOT EXISTS(SELECT 1 FROM imports owner WHERE owner.template_version_id=NEW.id AND owner.status='pending'))\nBEGIN SELECT RAISE(ABORT,'Active consumer requires a typed File binding'); END"
